class LegacyPricingSpec extends AnyFunSuite {
  test("quote output is pinned") {
    val got = legacyQuote("A-1", 2)
    val golden = Paths.get("src/test/resources/golden/quote_A-1.txt")
    if (sys.env.contains("UPDATE_GOLDEN"))
      Files.writeString(golden, got)            // review the diff, then commit
    assert(Files.readString(golden) == got)
  }
}
